  -- Класс Героя-Прыгуна (SuperJumperHero)
  namespace.class("SuperJumperHero", function (namespace)
    local Initialize, PerformMainAction, UpdateOverheadText, __ctor__
    __ctor__ = function (this, player, character, humanoid)
