      local billboard = head:FindFirstChild("OverheadDisplay", false)
      if billboard ~= nil then
        local label = System.cast(Roblox.TextLabel, billboard:FindFirstChild("DisplayLabel", false))
        if label ~= nil then
          label.Text = System.toString(this.Name) .. " [⚡ Супер Прыгун]"
          label.TextColor3 = Color3.fromRGB(255, 215, 0)
